use super::*;
use crate::OperatorInfo;
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::registry::tests::observe_ownership(operation)}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{registry:Registry,output:Option<Dictionary>}
#[test]
fn original_finished_output_cursor_preserves_same_owner_and_validates_contract_with_zero_birth(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{let(mut source,born,free)=observe(||{let mut registry=Registry::new();let name=row["name"].as_str().unwrap().to_string();let channel=ChannelSpec{code:String::new(),abbreviation:String::new(),name,full_name:String::new(),operators:Vec::new(),value_types:Vec::new(),item_types:Vec::new(),default:None,label:None,cardinality:Cardinality::from_symbol(row["cardinality"].as_str().unwrap()).unwrap()};registry.register_operator(OperatorInfo{id:"original-finished-output-原".into(),outputs:vec![channel],..Default::default()},Vec::new(),&[]);Sources{registry,output:Some(serde_json::from_value(row["output"].clone()).unwrap())}});let original=born-free;let pointer=source.output.as_ref().unwrap().entry_at_rank(0).map(|(_,value)|value as *const crate::Value);let(mut cursor,born,free)=observe(OperatorFinishCursor::new);assert_eq!((born,free),(0,0));let mut accepted=false;let mut terminal=false;
  for turn in 0..100000{let demand=source.registry.next_finish_job_demands("original-finished-output-原",&source.output,&cursor,copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for _ in 0..2{let(result,born,free)=observe(||source.registry.finish_job("original-finished-output-原",&mut source.output,&mut cursor,RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(result.is_none());assert_eq!(cursor.step_progress(),Default::default());assert_eq!((born,free),(0,0));}let(result,born,free)=observe(||source.registry.finish_job("original-finished-output-原",&mut source.output,&mut cursor,grant));assert_eq!((born,free),(0,0));assert!(cursor.step_progress().fits(grant));match result{Ok(Some(output))=>{assert_eq!(output.entry_at_rank(0).map(|(_,value)|value as *const crate::Value),pointer);source.output=Some(output);accepted=true;terminal=true;break;},Ok(None)=>assert_eq!(source.output.as_ref().unwrap().entry_at_rank(0).map(|(_,value)|value as *const crate::Value),pointer),Err(EvalError::Retained(error))=>{assert_eq!(error.retained_progress(),cursor.step_progress());assert_eq!(source.output.as_ref().unwrap().entry_at_rank(0).map(|(_,value)|value as *const crate::Value),pointer);terminal=true;break;},Err(error)=>panic!("unexpected original error {error:?}")};assert!(turn<99999,"original output contract stalled phase={} copy={copy}",cursor.phase);}
  assert!(terminal);assert_eq!(accepted,row["accepted"].as_bool().unwrap(),"id={}",row["id"]);let(mut owner,born,free)=observe(||ControlledRetirement::new(source).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut close_idle=0;for close_turn in 0..1000000{if owner.terminal_is_empty(){break;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;if step.progress()==RetainedCloneProgress::default(){close_idle+=1}else{close_idle=0}assert!(close_idle<64,"original output close stalled id={} copy={copy} turn={close_turn} demandcopy={} cap={} release={} depth={} receipt={:?}",row["id"],owner.next_copy_byte_demand().unwrap(),owner.next_capacity_byte_demand(copy).unwrap(),owner.next_release_byte_demand().unwrap(),owner.next_depth_demand().unwrap(),step.progress());}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(owner));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original output contract id={} copy={copy} accepted={accepted} original={original} born={births} release={releases} terminalDrop=0",row["id"]);
 }}
}
